//! Pixel-art icons in the spirit of Aseprite: every icon is a hand-placed 16×16 two-tone bitmap
//! (ink + shade), generated by `tools/gen_icons.py` into `icon_data.rs`. All icons live in one tiny
//! white atlas texture that is tinted with the ink colour and drawn at whole-pixel scales only, so
//! edges stay hard at every UI zoom. No image files, fonts or extra crates are involved.
use eframe::egui::{pos2, vec2, Color32, ColorImage, Context, Id, Painter, Pos2, Rect, TextureHandle, TextureOptions};

#[path = "icon_data.rs"]
mod data;
pub use data::Icon;
use data::ICON_ROWS;

/// Side of one icon in pixels.
pub const PX: usize = 16;
/// Atlas cell: the icon plus one empty pixel on every side, so neighbours never bleed in.
const CELL: usize = PX + 2;
const COLS: usize = 12;
/// Opacity of the shade tone ('+').
const SHADE_ALPHA: u8 = 110;

fn atlas_size() -> (usize, usize) {
    (COLS * CELL, ICON_ROWS.len().div_ceil(COLS) * CELL)
}

/// Builds the RGBA atlas: white ink, translucent white shade, transparent background.
fn atlas_rgba() -> (usize, usize, Vec<u8>) {
    let (w, h) = atlas_size();
    let mut px = vec![0u8; w * h * 4];
    for (i, (_, rows)) in ICON_ROWS.iter().enumerate() {
        let (ox, oy) = ((i % COLS) * CELL + 1, (i / COLS) * CELL + 1);
        for (y, row) in rows.iter().enumerate() {
            for (x, ch) in row.bytes().enumerate().take(PX) {
                let a = match ch {
                    b'#' => 255,
                    b'+' => SHADE_ALPHA,
                    _ => continue,
                };
                let o = ((oy + y) * w + ox + x) * 4;
                px[o..o + 4].copy_from_slice(&[255, 255, 255, a]);
            }
        }
    }
    (w, h, px)
}

fn atlas(ctx: &Context) -> TextureHandle {
    let id = Id::new("jank-icon-atlas");
    if let Some(t) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return t;
    }
    let (w, h, rgba) = atlas_rgba();
    let t = ctx.load_texture("icons", ColorImage::from_rgba_unmultiplied([w, h], &rgba), TextureOptions::NEAREST);
    ctx.data_mut(|d| d.insert_temp(id, t.clone()));
    t
}

fn uv(icon: Icon) -> Rect {
    let i = icon as usize;
    let (w, h) = atlas_size();
    let (x, y) = ((i % COLS) * CELL + 1, (i / COLS) * CELL + 1);
    Rect::from_min_size(pos2(x as f32 / w as f32, y as f32 / h as f32), vec2(PX as f32 / w as f32, PX as f32 / h as f32))
}

/// Draws `icon` centred on `c`, roughly `s` points tall, tinted with `col`. The bitmap is scaled by a
/// whole number of physical pixels and snapped to the pixel grid, so it never turns blurry.
pub fn draw(p: &Painter, icon: Icon, c: Pos2, s: f32, col: Color32) {
    let ctx = p.ctx();
    let ppp = ctx.pixels_per_point();
    let k = (s * ppp / PX as f32).round().max(1.0);
    let side = k * PX as f32 / ppp;
    let snap = |v: f32| (v * ppp).round() / ppp;
    let min = pos2(snap(c.x - side * 0.5), snap(c.y - side * 0.5));
    p.image(atlas(ctx).id(), Rect::from_min_size(min, vec2(side, side)), uv(icon), col);
}

/// Name of an icon as written in `tools/gen_icons.py` (used by tests and tooltips in debug views).
#[allow(dead_code)]
pub fn name(icon: Icon) -> &'static str {
    ICON_ROWS[icon as usize].0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn enum_order_matches_the_bitmap_table() {
        assert_eq!(Icon::ALL.len(), ICON_ROWS.len());
        for (i, icon) in Icon::ALL.iter().enumerate() {
            assert_eq!(*icon as usize, i);
            assert_eq!(format!("{icon:?}"), ICON_ROWS[i].0);
        }
    }

    #[test]
    fn every_bitmap_is_16_by_16_and_uses_only_known_tones() {
        for (n, rows) in ICON_ROWS.iter() {
            for r in rows {
                assert_eq!(r.len(), PX, "{n}");
                assert!(r.bytes().all(|b| matches!(b, b'#' | b'+' | b'.')), "{n}");
            }
            assert!(rows.iter().any(|r| r.contains('#')), "{n} is empty");
        }
    }

    #[test]
    fn atlas_cells_keep_a_transparent_border() {
        let (w, h, px) = atlas_rgba();
        assert_eq!(px.len(), w * h * 4);
        for i in 0..ICON_ROWS.len() {
            let (ox, oy) = ((i % COLS) * CELL, (i / COLS) * CELL);
            for t in 0..CELL {
                for (x, y) in [(ox + t, oy), (ox + t, oy + CELL - 1), (ox, oy + t), (ox + CELL - 1, oy + t)] {
                    assert_eq!(px[(y * w + x) * 4 + 3], 0);
                }
            }
        }
    }
}
